mapper.select:
SELECT id, authorization_id, account_type, visitor_type, login_type,
       grant_type, client_id, user_id, user_name, login_account,
       end_type, terminal,
       terminal_detail, client_ip, status, failure_code, failure_message, login_time, end_time,
       create_op, create_time, modify_op, modify_time
FROM log_login
WHERE deleted = 0

    AND authorization_id = #{query.authorizationId}

AND end_type = #{query.endType}
AND account_type = #{query.accountType}
AND visitor_type = #{query.visitorType}
AND login_type = #{query.loginType}
AND client_id = #{query.clientId}
AND user_id = #{query.userId}

    AND user_name LIKE CONCAT('%', #{query.userName}, '%')


    AND login_account LIKE CONCAT('%', #{query.loginAccount}, '%')

AND client_ip = #{query.clientIp}
AND status = #{query.status}
AND login_time >= #{query.loginTimeStart}
AND login_time <= #{query.loginTimeEnd}
AND end_time >= #{query.endTimeStart}
AND end_time <= #{query.endTimeEnd}
ORDER BY login_time DESC
